from test_bufftap import test, tests
G="local B=BuffTap; B.db.group=true; B.db.buffs.motw=false; B.db.buffs.thorns=true; spell(467,'Thorns'); IsInGroup=function() return true end; "
test('By default you still get a group buff like Thorns',G+"refresh(); assert(B.action and B.action.key=='thorns' and B.action.target=='player', B.action and B.action.target)")
test('Also on me off: Thorns goes to the group, not you',G+"B:GroupSettings(nil,true).buffSelf={thorns=false}; refresh(); assert(B.action and B.action.key=='thorns' and B.action.target~='player', B.action and B.action.target)")
test('Also on me off with Tanks: only the tank gets Thorns',G+"B:GroupSettings(nil,true).buffSelf={thorns=false}; B:GroupSettings(nil,true).buffRoles={thorns='tank'}; B.db.roleMarks['Player-party2']='TANK'; B.roleCache=nil; refresh(); assert(B.action and B.action.target=='party2', B.action and B.action.target)")
test('Solo, you always get it',G+"B:GroupSettings(nil,true).buffSelf={thorns=false}; IsInGroup=function() return false end; GetNumSubgroupMembers=function() return 0 end; UnitExists=function(u) return u=='player' end; refresh(); assert(B.action and B.action.target=='player')")
test('Also on me is saved per setup and survives cleanup',G+"B:GroupSettings('Party',true).buffSelf={thorns=false}; B:NormalizeGroupContexts(); assert(B:SelfRecipientAllowed(B:FindBuff('thorns'),'Party')==false and B:SelfRecipientAllowed(B:FindBuff('thorns'),'Raid')==true)")
test('Groups page has the Also on me switch',G+"B:Options(); local f=B.options; local row; for _,r in ipairs(f.assignRows or {}) do if r.def and r.def.key=='thorns' then row=r end end; if not row then f.selectedAssignment='thorns'; B:Options(); for _,r in ipairs(f.assignRows or {}) do if r.def and r.def.key=='thorns' then row=r end end end; assert(row,'row'); assert(row.selfCheck,'sc'); assert(row.selfCheck:GetChecked()==true,'chk '..tostring(row.selfCheck:GetChecked())); row.selfCheck:SetChecked(false); row.selfCheck.scripts.OnClick(row.selfCheck); assert(B:SelfRecipientAllowed(B:FindBuff('thorns'),B:EditingGroupContext())==false,'after')")
